                <div class="admin-panel"><div class="panel-head d-flex justify-content-between align-items-center"><div><h5 class="fw-bold mb-1">Recent Orders</h5><small class="text-secondary">Latest platform activity</small></div><button class="btn btn-sm btn-link text-decoration-none" onclick="AdminUI.show('orders')">View all</button></div><div class="panel-body p-0"><div class="table-responsive"><table class="table align-middle mb-0 dashboard-table" id="recentOrders"><thead><tr><th>Order</th><th>Customer</th><th>Branch</th><th>Total</th><th>Status</th><th>Time</th></tr></thead><tbody></tbody></table></div></div></div>
            </div>
            <div class="col-xl-4">
                <div class="admin-panel h-100"><div class="panel-head d-flex justify-content-between align-items-center"><div><h5 class="fw-bold mb-1">Branch Performance</h5><small class="text-secondary">Orders by branch</small></div><button class="btn btn-sm btn-link text-decoration-none" onclick="AdminUI.show('branches')">View all</button></div><div class="panel-body" id="branchPerformance"><div class="empty-state py-4">Loading branches…</div></div></div>
            </div>
        </div>
    </section>

    <section data-panel="orders" class="d-none">
        <div class="card food-card p-4"><div class="d-flex flex-wrap justify-content-between gap-2 mb-3"><div><h5 class="fw-bold mb-0">Order management</h5><small class="text-secondary">Advance orders through the central workflow.</small></div><div class="d-flex gap-2"><select id="orderStatusFilter" class="form-select"><option value="">All statuses</option><option>pending</option><option>confirmed</option><option>preparing</option><option>ready</option><option>assigned</option><option>picked_up</option><option>out_for_delivery</option><option>delivered</option><option>completed</option><option>cancelled</option></select><button class="btn btn-fh" onclick="AdminUI.loadOrders()">Refresh</button></div></div><div class="table-responsive"><table class="table align-middle" id="ordersTable"><thead><tr><th>Order</th><th>Customer</th><th>Branch</th><th>Status</th><th>Payment</th><th>Total</th><th></th></tr></thead><tbody></tbody></table></div></div>
    </section>

