            <div class="col-lg-4"><div class="card food-card p-4"><h5 class="fw-bold">Add category</h5><form id="categoryForm" class="vstack gap-2"><input class="form-control" name="name" placeholder="Category name" required><textarea class="form-control" name="description" placeholder="Description"></textarea><input class="form-control" name="sort_order" type="number" value="0" min="0"><button class="btn btn-fh">Create category</button></form></div></div>
            <div class="col-lg-8"><div class="card food-card p-4"><div class="d-flex justify-content-between"><h5 class="fw-bold">Categories</h5><button class="btn btn-sm btn-outline-secondary" onclick="AdminUI.loadCategories()">Refresh</button></div><div id="categoriesList"></div></div></div>
            <div class="col-lg-4"><div class="card food-card p-4"><h5 class="fw-bold">Add product</h5><form id="productForm" class="vstack gap-2"><select class="form-select" name="category_id" id="productCategory" required></select><input class="form-control" name="name" placeholder="Product name" required><textarea class="form-control" name="description" placeholder="Description"></textarea><input class="form-control" name="base_price" type="number" step="0.01" placeholder="Base price" required><input class="form-control" name="preparation_minutes" type="number" min="1" value="15"><select class="form-select" name="branch_id" id="productBranch"><option value="">No branch assignment yet</option></select><input class="form-control" name="branch_price" type="number" step="0.01" placeholder="Branch price (optional)"><button class="btn btn-fh">Create product</button></form></div></div>
            <div class="col-lg-8"><div class="card food-card p-4"><div class="d-flex justify-content-between"><h5 class="fw-bold">Products</h5><button class="btn btn-sm btn-outline-secondary" onclick="AdminUI.loadProducts()">Refresh</button></div><div class="table-responsive"><table class="table align-middle" id="productsTable"><thead><tr><th>Product</th><th>Category</th><th>Base</th><th>Branches</th><th>Options</th><th></th></tr></thead><tbody></tbody></table></div></div></div>
        </div>
