    <section data-panel="people" class="d-none"><div class="card food-card p-4"><div class="d-flex justify-content-between"><h5 class="fw-bold">People</h5><button class="btn btn-sm btn-fh" onclick="AdminUI.loadUsers()">Refresh</button></div><div class="table-responsive"><table class="table" id="usersTable"><thead><tr><th>Name</th><th>Email</th><th>Role</th><th>Branch</th><th>Status</th></tr></thead><tbody></tbody></table></div></div></section>

    <section data-panel="inventory" class="d-none"><div class="row g-4"><div class="col-lg-4"><div class="card food-card p-4"><h5 class="fw-bold">Add inventory item</h5><form id="inventoryForm" class="vstack gap-2"><select class="form-select" name="branch_id" id="inventoryBranch" required></select><input class="form-control" name="name" placeholder="Item name" required><input class="form-control" name="sku" placeholder="SKU" required><input class="form-control" name="unit" value="pcs" placeholder="Unit" required><input class="form-control" name="quantity" type="number" step="0.001" value="0"><input class="form-control" name="reorder_level" type="number" step="0.001" value="0"><input class="form-control" name="cost" type="number" step="0.01" value="0"><button class="btn btn-fh">Create item</button></form></div></div><div class="col-lg-8"><div class="card food-card p-4"><h5 class="fw-bold">Inventory</h5><div class="table-responsive"><table class="table" id="inventoryTable"><thead><tr><th>Item</th><th>Branch</th><th>Qty</th><th>Reorder</th><th>Cost</th><th>Adjust</th></tr></thead><tbody></tbody></table></div></div></div></div></section>

    <section data-panel="tables" class="d-none"><div class="card food-card p-4"><h5 class="fw-bold">Restaurant tables</h5><div class="table-responsive"><table class="table" id="tablesTable"><thead><tr><th>Table</th><th>Branch</th><th>Capacity</th><th>QR token</th><th>Status</th></tr></thead><tbody></tbody></table></div></div></section>

    <section data-panel="coupons" class="d-none"><div class="row g-4"><div class="col-lg-4"><div class="card food-card p-4"><h5 class="fw-bold">Create coupon</h5><form id="couponForm" class="vstack gap-2"><input class="form-control" name="code" placeholder="WELCOME50" required><select class="form-select" name="type"><option value="fixed">Fixed amount</option><option value="percent">Percent</option></select><input class="form-control" name="value" type="number" step="0.01" placeholder="Value" required><input class="form-control" name="minimum_order" type="number" step="0.01" value="0" placeholder="Minimum order"><input class="form-control" name="maximum_discount" type="number" step="0.01" placeholder="Maximum discount"><input class="form-control" name="starts_at" type="datetime-local"><input class="form-control" name="ends_at" type="datetime-local"><input class="form-control" name="usage_limit" type="number" min="1" placeholder="Usage limit"><button class="btn btn-fh">Create coupon</button></form></div></div><div class="col-lg-8"><div class="card food-card p-4"><h5 class="fw-bold">Coupons</h5><div class="table-responsive"><table class="table" id="couponsTable"><thead><tr><th>Code</th><th>Type</th><th>Value</th><th>Used</th><th>Validity</th><th></th></tr></thead><tbody></tbody></table></div></div></div></div></section>
</div>
