@push('scripts')
<script>
const AdminUI = (() => {
    let token = localStorage.getItem('fh_admin_token') || '';
    const esc = v => String(v ?? '').replace(/[&<>'"]/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]));
    const money = v => '₱' + Number(v || 0).toLocaleString(undefined,{minimumFractionDigits:2,maximumFractionDigits:2});
    const msg = (text, ok=false) => { console.warn('[FoodHub Admin]', text); };
    const json = async (url, options={}) => { const r=await fetch(url,{...options,headers:{'Accept':'application/json','Content-Type':'application/json',...(options.headers||{}),'Authorization':'Bearer '+token}}); const d=await r.json().catch(()=>({})); if(r.status===401){logout(false);throw new Error('Session expired.');} if(!r.ok) throw new Error(d.message || Object.values(d.errors||{}).flat().join(' ') || 'Request failed.'); return d; };
    const formData = form => Object.fromEntries(new FormData(form).entries());

    function show(section){ document.querySelectorAll('[data-admin-section]').forEach(a=>a.classList.toggle('active',a.dataset.adminSection===section)); document.querySelectorAll('[data-panel]').forEach(p=>p.classList.toggle('d-none',p.dataset.panel!==section)); if(section==='overview'){history.replaceState(null,'','#overview');} load(section); }
    async function load(section){ try { if(section==='overview') await loadOverview(); if(section==='orders') await loadOrders(); if(section==='menu'){await loadCategories();await loadProducts();} if(section==='branches') await loadBranches(); if(section==='people') await loadUsers(); if(section==='inventory') await loadInventory(); if(section==='tables') await loadTables(); if(section==='coupons') await loadCoupons(); } catch(e){ msg(e.message); } }
    async function loadOverview(){ const d=await json('/api/v1/admin/dashboard'); const cards=[['orders_today','Orders Today','bi-bag-check'],['sales_today','Total Revenue','bi-cash-stack'],['branches','Active Branches','bi-shop-window'],['customers','Total Customers','bi-people']]; document.getElementById('adminStats').innerHTML=cards.map(([k,l,icon],i)=>`<div class="col-12 col-sm-6 col-xl-3"><div class="admin-stat-card admin-stat-modern"><div class="d-flex justify-content-between align-items-start"><div class="icon"><i class="bi ${icon}"></i></div><span class="trend">${i===0?'Today':i===1?'Today':i===2?'Active':'Last 7 days'}</span></div><div class="small text-secondary mt-3 mb-1">${l}</div><div class="value">${k==='sales_today'?money(d[k]):esc(d[k])}</div><div class="stat-spark"></div></div></div>`).join(''); const rows=await json('/api/v1/admin/orders'); const orders=rows.data||[]; document.querySelector('#recentOrders tbody').innerHTML=orders.slice(0,8).map(o=>`<tr><td><strong>${esc(o.order_number)}</strong></td><td>${esc(o.customer?.name||'Guest')}</td><td>${esc(o.branch?.name||'—')}</td><td class="fw-bold">${money(o.grand_total)}</td><td><span class="status-pill status-${esc(o.status)}">${esc(o.status)}</span></td><td class="text-secondary small">${o.created_at?new Date(o.created_at).toLocaleTimeString([], {hour:'2-digit',minute:'2-digit'}):'—'}</td></tr>`).join('') || '<tr><td colspan="6" class="text-secondary py-5 text-center">No orders yet.</td></tr>'; const counts=Array(7).fill(0); const now=new Date(); orders.forEach(o=>{const dt=new Date(o.created_at||o.placed_at||now);const diff=Math.floor((Date.UTC(now.getFullYear(),now.getMonth(),now.getDate())-Date.UTC(dt.getFullYear(),dt.getMonth(),dt.getDate()))/86400000);if(diff>=0&&diff<7)counts[6-diff]++;}); const max=Math.max(...counts,1); const pts=counts.map((v,i)=>`${(i/6)*760},${210-(v/max)*175}`).join(' L'); document.getElementById('chartLine').setAttribute('d','M'+pts);document.getElementById('chartArea').setAttribute('d',`M0,210 L${pts} L760,210 Z`); const products=await json('/api/v1/admin/products'); const top=(products.data||products||[]).slice(0,5); document.getElementById('topProducts').innerHTML=top.length?top.map((p,i)=>`<div class="product-row"><div class="product-thumb"><i class="bi bi-egg-fried"></i></div><div class="flex-grow-1"><div class="d-flex justify-content-between gap-2"><strong>${esc(p.name)}</strong><span class="small fw-bold">${money(p.base_price)}</span></div><div class="small text-secondary">${esc(p.category?.name||'Menu item')}</div><div class="product-bar"><span style="width:${Math.max(22,100-i*16)}%"></span></div></div></div>`).join(''):'<div class="empty-state py-4">No products yet.</div>'; const branches=await json('/api/v1/admin/branches'); const branchRows=(branches||[]).slice(0,5); const maxOrders=Math.max(...branchRows.map(b=>Number(b.orders_count||0)),1); document.getElementById('branchPerformance').innerHTML=branchRows.length?branchRows.map(b=>`<div class="branch-row"><div class="d-flex justify-content-between mb-1"><strong>${esc(b.name)}</strong><span class="small fw-bold">${esc(b.orders_count||0)}</span></div><div class="product-bar"><span style="width:${Math.max(6,(Number(b.orders_count||0)/maxOrders)*100)}%"></span></div><div class="small text-secondary mt-1">${b.is_active?'Online':'Offline'}</div></div>`).join(''):'<div class="empty-state py-4">No branches yet.</div>'; }
    async function loadOrders(){ const status=document.getElementById('orderStatusFilter').value; const d=await json('/api/v1/admin/orders'+(status?'?status='+encodeURIComponent(status):'')); document.querySelector('#ordersTable tbody').innerHTML=d.data.map(o=>`<tr><td><strong>${esc(o.order_number)}</strong><div class="small text-secondary">${esc(o.fulfillment_type)}</div></td><td>${esc(o.customer?.name)}</td><td>${esc(o.branch?.name)}</td><td><select class="form-select form-select-sm" onchange="AdminUI.transition(${o.id},this.value)"><option value="${esc(o.status)}">${esc(o.status)}</option>${['pending','confirmed','preparing','ready','assigned','picked_up','out_for_delivery','delivered','completed','cancelled'].filter(s=>s!==o.status).map(s=>`<option value="${s}">${s}</option>`).join('')}</select></td><td>${esc(o.payment_status)}</td><td>${money(o.grand_total)}</td><td><button class="btn btn-sm btn-outline-secondary" onclick="AdminUI.detail(${o.id})">View</button></td></tr>`).join('') || '<tr><td colspan="7">No orders found.</td></tr>'; }
    async function detail(id){ const o=await json('/api/v1/admin/orders/'+id); const lines=(o.items||[]).map(i=>`${i.quantity} × ${i.product_name} = ${money(i.line_total)}`).join('\n'); alert(`${o.order_number}\nCustomer: ${o.customer?.name||''}\nStatus: ${o.status}\nPayment: ${o.payment_status}\nTotal: ${money(o.grand_total)}\n\n${lines}\n\nTimeline:\n${(o.status_history||[]).map(h=>h.status+' — '+new Date(h.created_at).toLocaleString()).join('\n')}`); }
    async function transition(id,status){ try{await json('/api/v1/admin/orders/'+id+'/transition',{method:'POST',body:JSON.stringify({status})});await loadOrders();}catch(e){alert(e.message);await loadOrders();} }
    async function loadBranches(){ const d=await json('/api/v1/admin/branches'); document.querySelector('#branchesTable tbody').innerHTML=d.map(b=>`<tr><td>${esc(b.name)}</td><td>${esc(b.code)}</td><td>${esc(b.orders_count)}</td><td>${esc(b.delivery_radius_km)} km</td><td><span class="badge ${b.is_active?'text-bg-success':'text-bg-secondary'}">${b.is_active?'Active':'Inactive'}</span></td></tr>`).join(''); fillSelect('productBranch',d,'id','name','No branch assignment yet'); fillSelect('inventoryBranch',d,'id','name'); }
    async function loadCategories(){ const d=await json('/api/v1/admin/categories'); document.querySelector('#categoriesList').innerHTML=d.map(c=>`<div class="d-flex justify-content-between align-items-center border-bottom py-2"><span><strong>${esc(c.name)}</strong><small class="text-secondary d-block">${esc(c.products_count)} products</small></span><span class="badge text-bg-light">${c.is_active?'Active':'Inactive'}</span></div>`).join('') || '<div class="text-secondary">No categories.</div>'; fillSelect('productCategory',d,'id','name'); }
    async function loadProducts(){ const d=await json('/api/v1/admin/products'); document.querySelector('#productsTable tbody').innerHTML=d.data.map(p=>`<tr><td><strong>${esc(p.name)}</strong><div class="small text-secondary">${p.is_active?'Active':'Inactive'}</div></td><td>${esc(p.category?.name)}</td><td>${money(p.base_price)}</td><td>${esc((p.branches||[]).map(b=>b.name).join(', ')||'Unassigned')}</td><td>${esc((p.options||[]).length)}</td><td><button class="btn btn-sm btn-outline-secondary" onclick="AdminUI.addOption(${p.id})">+ option</button></td></tr>`).join('') || '<tr><td colspan="6">No products.</td></tr>'; }
    async function addOption(id){ const name=prompt('Option name'); if(!name)return; const price=prompt('Option price','0'); if(price===null)return; try{await json('/api/v1/admin/products/'+id+'/options',{method:'POST',body:JSON.stringify({name,price:Number(price)})});await loadProducts();}catch(e){alert(e.message);} }
    async function loadUsers(){ const d=await json('/api/v1/admin/users'); document.querySelector('#usersTable tbody').innerHTML=d.data.map(u=>`<tr><td>${esc(u.name)}</td><td>${esc(u.email)}</td><td><span class="badge text-bg-light">${esc(u.role)}</span></td><td>${esc(u.branch?.name||'—')}</td><td><span class="badge ${u.is_active?'text-bg-success':'text-bg-secondary'}">${u.is_active?'Active':'Disabled'}</span></td></tr>`).join(''); }
    async function loadInventory(){ const d=await json('/api/v1/admin/inventory'); document.querySelector('#inventoryTable tbody').innerHTML=d.data.map(i=>`<tr><td>${esc(i.name)}<div class="small text-secondary">${esc(i.sku)}</div></td><td>${esc(i.branch?.name)}</td><td class="${Number(i.quantity)<=Number(i.reorder_level)?'text-danger fw-bold':''}">${esc(i.quantity)} ${esc(i.unit)}</td><td>${esc(i.reorder_level)}</td><td>${money(i.cost)}</td><td><button class="btn btn-sm btn-outline-secondary" onclick="AdminUI.adjust(${i.id})">Adjust</button></td></tr>`).join(''); }
    async function adjust(id){const delta=prompt('Quantity change (+/-)','1');if(delta===null)return;try{await json('/api/v1/admin/inventory/'+id+'/adjust',{method:'POST',body:JSON.stringify({quantity_delta:Number(delta),reason:'Admin adjustment'})});await loadInventory();}catch(e){alert(e.message);}}
    async function loadTables(){ const d=await json('/api/v1/admin/tables'); document.querySelector('#tablesTable tbody').innerHTML=d.map(t=>`<tr><td>${esc(t.name)}<div class="small text-secondary">${esc(t.code)}</div></td><td>${esc(t.branch?.name)}</td><td>${esc(t.capacity)}</td><td><code>${esc(t.qr_token)}</code></td><td><select class="form-select form-select-sm" onchange="AdminUI.tableStatus(${t.id},this.value)">${['available','occupied','reserved','cleaning'].map(s=>`<option ${s===t.status?'selected':''}>${s}</option>`).join('')}</select></td></tr>`).join(''); }
    async function tableStatus(id,status){try{await json('/api/v1/admin/tables/'+id,{method:'PUT',body:JSON.stringify({status})});}catch(e){alert(e.message);await loadTables();}}
    async function loadCoupons(){ const d=await json('/api/v1/admin/coupons'); document.querySelector('#couponsTable tbody').innerHTML=d.map(c=>`<tr><td><strong>${esc(c.code)}</strong></td><td>${esc(c.type)}</td><td>${c.type==='percent'?esc(c.value)+'%':money(c.value)}</td><td>${esc(c.used_count)} / ${esc(c.usage_limit??'∞')}</td><td><small>${c.starts_at?new Date(c.starts_at).toLocaleDateString():'Now'} – ${c.ends_at?new Date(c.ends_at).toLocaleDateString():'No end'}</small></td><td><button class="btn btn-sm btn-outline-danger" onclick="AdminUI.deleteCoupon(${c.id})">Delete</button></td></tr>`).join('') || '<tr><td colspan="6">No coupons.</td></tr>'; }
    async function deleteCoupon(id){if(!confirm('Delete this coupon?'))return;try{await json('/api/v1/admin/coupons/'+id,{method:'DELETE'});await loadCoupons();}catch(e){alert(e.message);}}
    function fillSelect(id,rows,valueKey,labelKey,first){const el=document.getElementById(id);if(!el)return;const firstOpt=first!==undefined?`<option value="">${esc(first)}</option>`:'';el.innerHTML=firstOpt+rows.map(x=>`<option value="${esc(x[valueKey])}">${esc(x[labelKey])}</option>`).join('');}
    async function bootstrap(){if(!token){window.location.replace('/login/admin');return;}try{const d=await json('/api/v1/me');if(d.role!=='admin')throw new Error('Saved session is not an administrator.');document.getElementById('adminUserTop').textContent=d.name||d.email;show((location.hash||'#overview').slice(1)||'overview');}catch(e){logout(false);}}
    async function logout(showMsg=true){if(token){try{await fetch('/api/v1/auth/logout',{method:'POST',headers:{Authorization:'Bearer '+token,Accept:'application/json'}})}catch(e){}}token='';localStorage.removeItem('fh_admin_token');window.location.replace('/login/admin');}

    document.querySelectorAll('[data-admin-section]').forEach(a=>a.addEventListener('click',e=>{e.preventDefault();show(a.dataset.adminSection);document.getElementById('adminSidebar')?.classList.remove('is-open');document.getElementById('adminOverlay')?.classList.remove('show');history.replaceState(null,'','#'+a.dataset.adminSection);}));
    document.getElementById('adminMenuToggle')?.addEventListener('click',()=>{document.getElementById('adminSidebar')?.classList.add('is-open');document.getElementById('adminOverlay')?.classList.add('show');});
    document.getElementById('adminOverlay')?.addEventListener('click',()=>{document.getElementById('adminSidebar')?.classList.remove('is-open');document.getElementById('adminOverlay')?.classList.remove('show');});
    document.getElementById('adminLogout').addEventListener('click',()=>logout());
    document.getElementById('branchForm').addEventListener('submit',async e=>{e.preventDefault();try{await json('/api/v1/admin/branches',{method:'POST',body:JSON.stringify(formData(e.target))});e.target.reset();await loadBranches();alert('Branch created.');}catch(x){alert(x.message);}});
    document.getElementById('categoryForm').addEventListener('submit',async e=>{e.preventDefault();try{await json('/api/v1/admin/categories',{method:'POST',body:JSON.stringify(formData(e.target))});e.target.reset();await loadCategories();await loadProducts();alert('Category created.');}catch(x){alert(x.message);}});
    document.getElementById('productForm').addEventListener('submit',async e=>{e.preventDefault();try{const d=formData(e.target);['category_id','branch_id'].forEach(k=>{if(d[k])d[k]=Number(d[k]);});d.base_price=Number(d.base_price);if(d.branch_price)d.branch_price=Number(d.branch_price);d.preparation_minutes=Number(d.preparation_minutes);await json('/api/v1/admin/products',{method:'POST',body:JSON.stringify(d)});e.target.reset();await loadProducts();alert('Product created.');}catch(x){alert(x.message);}});
    document.getElementById('inventoryForm').addEventListener('submit',async e=>{e.preventDefault();try{const d=formData(e.target);d.branch_id=Number(d.branch_id);['quantity','reorder_level','cost'].forEach(k=>d[k]=Number(d[k]));await json('/api/v1/admin/inventory',{method:'POST',body:JSON.stringify(d)});e.target.reset();await loadInventory();alert('Inventory item created.');}catch(x){alert(x.message);}});
    document.getElementById('couponForm').addEventListener('submit',async e=>{e.preventDefault();try{const d=formData(e.target);d.value=Number(d.value);['minimum_order','maximum_discount','usage_limit'].forEach(k=>{if(d[k])d[k]=Number(d[k]);else delete d[k];});['starts_at','ends_at'].forEach(k=>{if(!d[k])delete d[k];else d[k]=new Date(d[k]).toISOString();});await json('/api/v1/admin/coupons',{method:'POST',body:JSON.stringify(d)});e.target.reset();await loadCoupons();alert('Coupon created.');}catch(x){alert(x.message);}});
    document.getElementById('orderStatusFilter').addEventListener('change',loadOrders);

    return {show,loadOrders,loadCategories,loadProducts,loadUsers,detail,transition,addOption,adjust,tableStatus,deleteCoupon};
})();
window.AdminUI=AdminUI;
document.getElementById('adminToday')?.replaceChildren(document.createTextNode(new Intl.DateTimeFormat(undefined,{weekday:'long',month:'long',day:'numeric',year:'numeric'}).format(new Date())));
AdminUI.show('overview');
</script>
@endpush
